-- Who is asking: SELECT authz.act_as('user', '42') first in each transaction (a signed session).
DO $u$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE oid = to_regprocedure('authz.uid()')
             AND prorettype <> 'bigint'::regtype) THEN
    RAISE EXCEPTION 'authz.uid() returns another type than this policy''s user ids (bigint); drop it first (DROP FUNCTION authz.uid() CASCADE drops what uses it) [AZ606]';
  END IF;
END $u$;

CREATE OR REPLACE FUNCTION authz.uid() RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $uid$ BEGIN RETURN CASE WHEN authz_int.session_ok() AND coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'bigint') THEN pg_catalog.current_setting('authz.user_id', true)::bigint END; END $uid$;

CREATE SCHEMA authz_gen;
CREATE SCHEMA authz_int;

-- Signed sessions: the key, made once and kept in authz.settings (the app role can't read either)
CREATE TABLE authz_int.session_key (ipad bytea NOT NULL, opad bytea NOT NULL);
INSERT INTO authz.settings (key, value)
  VALUES ('session_key', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  ON CONFLICT (key) DO NOTHING;
DO $sk$
DECLARE k bytea; i bytea; o bytea;
BEGIN
  SELECT decode(value, 'hex') INTO k FROM authz.settings WHERE key = 'session_key';
  k := k || decode(repeat('00', 64 - length(k)), 'hex');
  i := k; o := k;
  FOR n IN 0..63 LOOP
    i := set_byte(i, n, get_byte(k, n) # 54);
    o := set_byte(o, n, get_byte(k, n) # 92);
  END LOOP;
  INSERT INTO authz_int.session_key VALUES (i, o);
END $sk$;
-- HMAC-SHA256 of who is signed in, this backend and this transaction
CREATE FUNCTION authz_int.session_sig() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex');
END $f$;
-- signs the settings as they are now: for rowfence's own functions, after they switch who is signed in
CREATE FUNCTION authz_int.sign() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM set_config('authz.session', authz_int.session_sig(), true);
END $f$;
-- Are the settings to be believed? PL/pgSQL, so its plans are kept for the session, and not a definer: all its
-- callers run as the owner. (OR runs left to right: the refusal is asked only when the signature doesn't match.)
CREATE FUNCTION authz_int.session_ok() RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN coalesce(current_setting('authz.session', true) = pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex'), false) OR authz_int.session_refused();
END $f$;
-- When the signature doesn't match: true for the owner's and superusers' sessions, else an error saying why
CREATE FUNCTION authz_int.session_refused() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_sig text := coalesce(current_setting('authz.session', true), '');
BEGIN
  -- the policy's owner and superusers say who is signed in by setting it (psql, migrations, tests)
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN true;
  END IF;
  IF v_sig <> '' THEN
    RAISE EXCEPTION 'who is signed in was changed after signing in' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'say who is signed in with authz.act_as(), never by setting authz.user_id or the other authz settings '
             '(rowfence help AZ702)';
  ELSIF coalesce(current_setting('authz.user_id', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.user_id was set directly, so it is not believed' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'sign in with SELECT authz.act_as(''user'', ''42''), authz.login_key() or authz.login_jwt() (rowfence help AZ702)';
  END IF;
  RAISE EXCEPTION 'nobody signed in in this transaction' USING ERRCODE = 'invalid_authorization_specification',
    HINT = 'start each transaction with SELECT authz.act_as(''user'', ''42''), or authz.act_as(NULL, NULL) for nobody '
           '(or authz.login_key() / authz.login_jwt()) (rowfence help AZ701)';
END $f$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7' (invalid ids as they are)
CREATE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'service' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'project' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'note' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'message' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;

-- the signed-in service, if a service is signed in
CREATE FUNCTION authz_int."service__me"() RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $me$ BEGIN RETURN CASE WHEN authz_int.session_ok() AND pg_catalog.current_setting('authz.principal_type', true) = 'service' AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'bigint') THEN pg_catalog.current_setting('authz.user_id', true)::bigint END; END $me$;
-- Who is signed in, whatever their type: SELECT * FROM authz.principal()
CREATE FUNCTION authz.principal() RETURNS TABLE (principal_type text, principal_id text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  principal_type := coalesce(nullif(pg_catalog.current_setting('authz.principal_type', true), ''), 'user');
  CASE principal_type
    WHEN 'user' THEN principal_id := authz.uid()::text;
    WHEN 'service' THEN principal_id := authz_int."service__me"()::text;
    ELSE RETURN;
  END CASE;
  IF principal_id IS NOT NULL THEN RETURN NEXT; END IF;
END $f$;
-- how the audit trail and created_by name who acted: a user's id, or type:id for other principals
CREATE FUNCTION authz_int.actor() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN CASE WHEN NOT authz_int.session_ok() THEN NULL
              WHEN coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') THEN nullif(current_setting('authz.user_id', true), '')
              ELSE pg_catalog.current_setting('authz.principal_type', true) || ':' || nullif(current_setting('authz.user_id', true), '') END;
END $f$;

-- per type: its table, key, how to find a row x by an id ($1, text), and a row's id (columns unqualified)
CREATE TABLE authz_int.types (name text PRIMARY KEY, tbl text NOT NULL, pk text NOT NULL, pktype text NOT NULL,
  keytype text NOT NULL, find text NOT NULL, id_of text NOT NULL, principal boolean NOT NULL);

INSERT INTO authz_int.types VALUES
  ('user', '"app"."users"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', true),
  ('service', '"app"."services"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', true),
  ('project', '"app"."projects"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', false),
  ('note', '"app"."notes"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', false),
  ('message', '"app"."inbox"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', false);

CREATE TABLE authz_int.perms (type text, perm text, PRIMARY KEY (type, perm));

INSERT INTO authz_int.perms VALUES
  ('project', 'edit'),
  ('project', 'view'),
  ('note', 'edit'),
  ('note', 'view'),
  ('message', 'read');

CREATE TABLE authz_int.locks (type text PRIMARY KEY, n bigint NOT NULL);

-- each inheritance table's definition and the tables it reads, to keep it on the next apply if they are the same
CREATE TABLE authz_int.trees (name text PRIMARY KEY, hash text NOT NULL, oids oid[] NOT NULL);

CREATE TABLE authz_int.shared_relations (object_type text, relation text, subject text, shared_by text, required text[], loc text, PRIMARY KEY (object_type, relation, subject));

DO $w$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares g WHERE g.relation NOT LIKE 'role:%' AND NOT EXISTS (
    SELECT 1 FROM authz_int.shared_relations s WHERE s.object_type = g.object_type AND s.relation = g.relation
      AND s.subject = CASE WHEN g.subject_type IN ('anyone', 'link') THEN g.subject_type
                           WHEN g.subject_id = '*' AND g.subject_relation = '' THEN g.subject_type || ':*'
                           WHEN g.subject_relation <> '' THEN g.subject_type || '#' || g.subject_relation
                           ELSE g.subject_type END);
  IF n > 0 THEN
    RAISE WARNING '% shares are for relations this policy does not declare as shared; they are kept, but grant nothing', n;
  END IF;
END $w$;

CREATE TABLE authz_int.role_subjects (object_type text, subject text, PRIMARY KEY (object_type, subject));

CREATE TABLE authz_int.role_grantable (object_type text, permission text, PRIMARY KEY (object_type, permission));

CREATE TABLE authz_int.caveats (name text PRIMARY KEY);

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND (c.relname LIKE 'shares\_obj\_%' OR c.relname LIKE 'grants\_obj\_%')
             AND c.relname <> ALL (ARRAY['shares_obj_user_bigint', 'shares_obj_service_bigint', 'shares_obj_project_bigint', 'shares_obj_note_bigint', 'shares_obj_message_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_service_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'service';
CREATE INDEX IF NOT EXISTS "shares_obj_project_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'project';
CREATE INDEX IF NOT EXISTS "shares_obj_note_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'note';
CREATE INDEX IF NOT EXISTS "shares_obj_message_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'message';

-- Scopes: what a token may do (policy 'scope' lines; 'read' is built in unless redefined)
CREATE TABLE authz_int.scope_items (scope text, kind text, qual text, word text);
INSERT INTO authz_int.scope_items VALUES
  ('read', 'cmd', NULL, 'select'),
  ('read', 'perm', NULL, '*');

-- the scopes this transaction is limited to (NULL: not limited); believed only if signed, like the user
CREATE FUNCTION authz_int.scopes_active() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE WHEN NOT authz_int.session_ok() THEN ARRAY[]::text[]
              WHEN coalesce(current_setting('authz.scopes', true), '') = '' THEN NULL
              ELSE ARRAY(SELECT btrim(x) FROM unnest(string_to_array(current_setting('authz.scopes', true), ',')) x
                         WHERE btrim(x) <> '') END $f$;
-- may this transaction run a command on a table?
CREATE FUNCTION authz_int.scope_cmd(p_table text, p_cmd text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                              AND i.word = p_cmd AND (i.qual IS NULL OR i.qual = p_table))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction ask about (or use) a permission?
CREATE FUNCTION authz_int.scope_perm(p_type text, p_perm text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'perm'
                              AND (i.word = p_perm OR i.word = '*') AND (i.qual IS NULL OR i.qual = p_type))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction change anything? (not while viewing as someone, not with read-only scopes)
CREATE FUNCTION authz_int.writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(current_setting('authz.acting_user', true), '') = ''
     AND (s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                               AND i.word <> 'select'))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
CREATE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ704';
  END IF;
END $f$;
-- the role that called (inside SECURITY DEFINER functions current_user is the owner)
CREATE FUNCTION authz_int.caller_role() RETURNS text
LANGUAGE sql STABLE AS $f$
  SELECT CASE WHEN current_setting('role') = 'none' THEN session_user::text ELSE current_setting('role') END $f$;
-- The caller is an administrator, not the app: a superuser, BYPASSRLS, or the policy's owner (or a member of it)
CREATE FUNCTION authz_int.caller_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce((SELECT r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid, n.nspowner, 'MEMBER')
                   FROM pg_roles r, pg_namespace n
                   WHERE r.rolname = authz_int.caller_role() AND n.nspname = 'authz_int'), false) $f$;
-- one row in the audit trail
CREATE FUNCTION authz_int.audit(p_action text, p_object_type text, p_object_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text, p_detail jsonb) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation,
                           subject_type, subject_id, subject_relation, detail, reason)
  VALUES (authz_int.caller_role(), authz_int.actor(),
          nullif(current_setting('authz.acting_user', true), ''), p_action, p_object_type, p_object_id, p_relation,
          p_subject_type, p_subject_id, p_subject_relation, p_detail,
          nullif(current_setting('authz_ctx.reason', true), '')) $f$;

-- The change feed: objects whose access may have changed. Consumers poll authz.changes_since(pos).
-- NOTIFY on channel authz_changes only with INSERT INTO authz.settings VALUES ('notify_changes', 'on'):
-- Postgres commits notifying transactions one at a time, so it would queue every write.
CREATE FUNCTION authz_int.changed(p_type text, p_ids text[], p_cause text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_pos bigint;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  INSERT INTO authz.changes (object_type, object_ids, cause) VALUES (p_type, p_ids, p_cause) RETURNING pos INTO v_pos;
  IF (SELECT s.value FROM authz.settings s WHERE s.key = 'notify_changes') = 'on' THEN
    PERFORM pg_notify('authz_changes', v_pos::text);
  END IF;
END $f$;
-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowfence help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days.
CREATE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_to bigint; n bigint;
BEGIN
  SELECT max(c.pos) INTO v_to FROM authz.changes c WHERE c.at < now() - v_keep;
  IF v_to IS NULL THEN RETURN 0; END IF;
  DELETE FROM authz.changes c WHERE c.pos <= v_to;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text)
    ON CONFLICT (key) DO UPDATE SET value = greatest(authz.settings.value::bigint, v_to)::text;
  RETURN n;
END $f$;
-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING HINT = 'rowfence help AZ710';
  END IF;
  v_before := now() - p_keep;
  PERFORM set_config('authz_int.trim_before', v_before::text, true);
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  PERFORM set_config('authz_int.trim_before', '', true);
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit()
CREATE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.at < nullif(current_setting('authz_int.trim_before', true), '')::timestamptz THEN RETURN OLD; END IF;
  END IF;
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ711';
END $f$;
CREATE TRIGGER authz_audit_append_only BEFORE UPDATE OR DELETE ON authz.audit
  FOR EACH ROW EXECUTE FUNCTION authz_int.audit_is_append_only();
CREATE TRIGGER authz_audit_no_truncate BEFORE TRUNCATE ON authz.audit
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int.audit_is_append_only();

-- shares and role assignments
CREATE FUNCTION authz_int.on_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  IF TG_OP = 'UPDATE' AND OLD.object_id <> NEW.object_id THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_grant_audit AFTER INSERT OR UPDATE OR DELETE ON authz.shares
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_grant();
CREATE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    PERFORM authz_int.audit(CASE TG_OP WHEN 'DELETE' THEN 'role_permission_removed' ELSE 'role_permission_added' END,
      NULL, NULL, 'role:' || CASE WHEN TG_OP = 'DELETE' THEN OLD.role_id ELSE NEW.role_id END, NULL, NULL, NULL,
      jsonb_build_object('permission', CASE WHEN TG_OP = 'DELETE' THEN OLD.permission ELSE NEW.permission END));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_audit AFTER INSERT OR UPDATE OR DELETE ON authz.roles
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();
CREATE TRIGGER authz_role_perm_audit AFTER INSERT OR DELETE ON authz.role_permissions
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'service' AND NOT EXISTS (SELECT 1 FROM "app"."services" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'service' AND NOT EXISTS (SELECT 1 FROM "app"."services" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'project' AND NOT EXISTS (SELECT 1 FROM "app"."projects" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'project' AND NOT EXISTS (SELECT 1 FROM "app"."projects" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'note' AND NOT EXISTS (SELECT 1 FROM "app"."notes" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'note' AND NOT EXISTS (SELECT 1 FROM "app"."notes" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'message' AND NOT EXISTS (SELECT 1 FROM "app"."inbox" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'message' AND NOT EXISTS (SELECT 1 FROM "app"."inbox" x WHERE x."id"::text = g.subject_id);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions)
CREATE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- relations ('role:<id>') of the custom roles that include a permission
CREATE FUNCTION authz_int.role_relations(p_type text, p_perm text) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(array_agg('role:' || r.id), '{}') FROM authz.roles r
  JOIN authz.role_permissions p ON p.role_id = r.id
  WHERE r.object_type = p_type AND p.permission = p_perm $f$;
-- deleting a role removes its assignments
CREATE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_gone AFTER DELETE ON authz.roles
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int.role_gone();

-- trees kept but no longer used (none, normally) go with the holding schema
DROP SCHEMA authz_keep CASCADE;

-- relationships kept in app.members
CREATE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'project' AS ot, x."project_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'project' AS ot, x."project_id"::text AS oid, 'member' AS rel, 'user' AS st, x."user_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;
-- @object trigger "authz_rel_audit_1_ins" ON "app"."members"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."members"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_ins" AFTER INSERT ON "app"."members" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_ins"()';
  ELSE
    RAISE NOTICE '"app"."members" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;
CREATE FUNCTION authz_int."rel_audit_1_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
