DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."inbox"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_message_col_audit_row" AFTER UPDATE ON "app"."inbox" FOR EACH ROW WHEN (OLD."recipient_id" IS DISTINCT FROM NEW."recipient_id") EXECUTE FUNCTION authz_int."message__col_audit_row"()';
  ELSE
    RAISE NOTICE '"app"."inbox" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

