CREATE FUNCTION authz_gen."app.projects:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."projects"; r_new "app"."projects";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for app.projects: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.projects', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."projects" x WHERE x."id" = p_id::bigint;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.projects: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for app.projects: nobody may update its rows'];
END $f$;

