-- app.inbox insert (line 41): signed_in and {sender_id = authz.uid()}
CREATE POLICY "authz_insert" ON "app"."inbox" FOR INSERT TO conf_app
  WITH CHECK (((SELECT authz_int.scope_cmd('app.inbox', 'insert')) AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    AND coalesce((sender_id = (SELECT authz.uid())), false)))
    OR authz_gen."app.inbox:insert:refuse"(ROW("inbox".*)::"app"."inbox"));

COMMENT ON POLICY "authz_insert" ON "app"."inbox" IS 'authzc';

-- Foreign keys that delete governed rows skip row-level security
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child, con.confrelid::regclass AS parent
           FROM pg_constraint con
           WHERE con.contype = 'f' AND con.confdeltype = 'c' AND con.conrelid IN ('"app"."projects"'::regclass, '"app"."notes"'::regclass, '"app"."inbox"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is ON DELETE CASCADE: deleting a row of % also deletes rows of %, and cascades skip row-level security, so a user could remove rows they cannot see. Use ON DELETE RESTRICT unless that is intended.',
      c.conname, c.child, c.parent, c.child;
  END LOOP;
END $fk$;

-- Column privileges: masked columns are read through the masked view only
DO $mc$
DECLARE r record; cols text;
BEGIN
  -- tables that are no longer masked get back the table-wide SELECT they had
  FOR r IN SELECT * FROM authz.masked_tables WHERE (tbl || '|' || role) <> ALL (ARRAY[]::text[]) LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;

END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_allowed boolean; v_bigint bigint;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")) FROM "app"."projects" o WHERE o."id" = v_bigint), false);
        WHEN 'view' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id")) FROM "app"."projects" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id")) FROM "app"."notes" o WHERE o."id" = v_bigint), false);
        WHEN 'view' THEN RETURN coalesce((SELECT EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id") FROM "app"."notes" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN RETURN coalesce((SELECT coalesce(o."recipient_id" = (SELECT authz.uid()), false) FROM "app"."inbox" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'project.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'project.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."projects" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."project__service" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."project__owner" v WHERE v.id = o."project_id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'note.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > p_after::bigint AND EXISTS (SELECT 1 FROM authz_gen."project__view" v WHERE v.id = o."project_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'message.read' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE coalesce(o."recipient_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE coalesce(o."recipient_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."inbox" o
        WHERE o."id" > p_after::bigint AND coalesce(o."recipient_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'project' THEN names := ARRAY['edit', 'view']::text[];
    WHEN 'note' THEN names := ARRAY['edit', 'view']::text[];
    WHEN 'message' THEN names := ARRAY['read']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

-- The permissions the user holds on many objects, in one call (a list's buttons): SELECT * FROM authz.perms_of('folder', ARRAY['1', '2'])
CREATE FUNCTION authz.perms_of(p_type text, p_ids text[]) RETURNS TABLE (id text, perms text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN QUERY SELECT x, authz.perms(p_type, x) FROM unnest(p_ids) WITH ORDINALITY u(x, n) ORDER BY n;
END $f$;
CREATE FUNCTION authz.can(p_type text, p_id bigint, p_perm text) RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT authz.can(p_type, p_id::text, p_perm) $$;
CREATE FUNCTION authz.perms(p_type text, p_id bigint) RETURNS text[] LANGUAGE sql STABLE AS
  $$ SELECT authz.perms(p_type, p_id::text) $$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowfence help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING ERRCODE = 'foreign_key_violation', HINT = 'rowfence help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowfence help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ706';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowfence help AZ707';
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;
CREATE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;
CREATE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz.can(p_type, p_id, v_by) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;
CREATE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;
CREATE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation) $$;

-- A link anyone holding the token can use: returns the token once (only its hash is stored).
-- Requests present it with SET LOCAL authz_ctx.links = '<token>'.
CREATE FUNCTION authz.create_link(p_type text, p_id text, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
BEGIN
  PERFORM authz.share(p_type, p_id, p_relation, 'link', encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
                      '', p_expires_at);
  RETURN v_token;
END $f$;
CREATE FUNCTION authz.create_link(p_type text, p_id bigint, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE sql AS $$ SELECT authz.create_link(p_type, p_id::text, p_relation, p_expires_at) $$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowfence help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowfence help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, p_owner_id, p_object_type, p_name, authz.uid()::text) RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;
CREATE FUNCTION authz.create_role(p_owner_type text, p_owner_id bigint, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.create_role(p_owner_type, p_owner_id::text, p_object_type, p_name, p_permissions) $$;
CREATE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowfence help AZ706'; END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;
CREATE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;
CREATE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;

-- Why a write is or would be refused, as the signed-in user: an insert (p_row: the new row as JSON), or an
-- update or delete of the row whose id is p_id (for an update, p_row: the new values). NULL when that row isn't
-- there or the user can't see it (404, not 403). SELECT authz.explain_rule('app.files', 'update', '11')
CREATE FUNCTION authz.explain_rule(p_table text, p_command text, p_id text DEFAULT NULL, p_row jsonb DEFAULT NULL)
RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_command IS NULL OR p_command NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION 'explain_rule explains insert, update or delete, not %', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowfence help AZ710';
  END IF;
  CASE p_table
    WHEN 'app.projects' THEN RETURN authz_gen."app.projects:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.notes' THEN RETURN authz_gen."app.notes:rules:explain"(p_command, p_id, p_row);
    WHEN 'app.inbox' THEN RETURN authz_gen."app.inbox:rules:explain"(p_command, p_id, p_row);
    ELSE RAISE EXCEPTION 'the policy has no rules for table %', p_table USING ERRCODE = 'undefined_table', HINT = 'rowfence help AZ707';
  END CASE;
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in with authz.act_as(), as the caller: so only a backend trusted to sign anyone in can
-- use it, as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
CREATE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowfence help AZ704';
  END IF;
  BEGIN
    FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
      PERFORM authz.act_as(p_principal_type, v_u);
      IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM authz.act_as(v_pt, v_me);
    RAISE;
  END;
  PERFORM authz.act_as(v_pt, v_me);
END $f$;
CREATE FUNCTION authz.who_among(p_type text, p_id bigint, p_perm text, p_users text[], p_principal_type text DEFAULT 'user') RETURNS SETOF text LANGUAGE sql VOLATILE AS
  $$ SELECT * FROM authz.who_among(p_type, p_id::text, p_perm, p_users, p_principal_type) $$;

-- these functions call each other; their bodies are checked when first used
SET LOCAL check_function_bodies = off;

CREATE FUNCTION authz_int."project__owner__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "app"."projects" r WHERE r."id" = p_id AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."project__member__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT s."user_id" FROM "app"."members" s WHERE s."project_id" = p_id
$f$;

CREATE FUNCTION authz_int."project__service__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT NULL::bigint WHERE false
$f$;

CREATE FUNCTION authz_int."note__author__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."author_id" FROM "app"."notes" r WHERE r."id" = p_id AND r."author_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."message__recipient__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."recipient_id" FROM "app"."inbox" r WHERE r."id" = p_id AND r."recipient_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."project__edit__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."project__owner__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."project__member__who"(p_id) x)
$f$;

CREATE FUNCTION authz_int."project__view__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT u."id" FROM "app"."users" u
$f$;

CREATE FUNCTION authz_int."note__edit__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."note__author__who"(p_id) x)
  UNION ALL
  (SELECT x FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg, LATERAL authz_int."project__owner__who"(tg.id) x)
$f$;

CREATE FUNCTION authz_int."note__view__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg, LATERAL authz_int."project__view__who"(tg.id) x
$f$;

CREATE FUNCTION authz_int."message__read__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM authz_int."message__recipient__who"(p_id) x
$f$;

CREATE FUNCTION authz_int."project__owner__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."projects" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'owner: owner_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold project.owner';
END $f$;

CREATE FUNCTION authz_int."project__member__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."project_id" AS id FROM "app"."members" s WHERE s."user_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'member: a row in app.members names you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold project.member';
END $f$;

CREATE FUNCTION authz_int."project__service__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."project_id" AS id FROM "app"."project_services" s WHERE s."service_id" = (SELECT authz_int."service__me"())) THEN
    RETURN NEXT pad || 'yes  ' || 'service: a row in app.project_services names' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold project.service';
END $f$;

CREATE FUNCTION authz_int."project__edit__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."project__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'project.edit = owner or member';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."project__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__owner__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."project__member");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'member';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__member__why"(p_id, p_depth + 1, p_seen); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."project__view__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."project__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'project.view = edit or service or {public}';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."project__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__edit__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."project__service");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'service';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__service__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "app"."projects" r WHERE coalesce((public), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{public}';
  END;
END $f$;

CREATE FUNCTION authz_int."note__project__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN

  RETURN NEXT pad || 'no   you do not hold note.project';
END $f$;

CREATE FUNCTION authz_int."note__author__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."notes" r WHERE r."author_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'author: author_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold note.author';
END $f$;

CREATE FUNCTION authz_int."note__edit__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."note__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'note.edit = author or project.owner';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."note__author");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'author';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."note__author__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."note__project__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'project.owner';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'project is project '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has owner' ELSE ', without owner' END;
      IF NOT ('project:owner:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."project__owner__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('project:owner:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

CREATE FUNCTION authz_int."note__view__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."note__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'note.view = project.view';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."note__project__view");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'project.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = p_id AND r."project_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'project is project '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('project:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."project__view__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('project:view:' || v_t.id));
      END IF;
    END LOOP;
  END;
END $f$;

